/// The extension IEs of `HOReport-ExtIEs` (NGAP-IEs). IEs not defined here are kept in `unknown_ies`.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct HoReportExtIes {
    /// `id-ExtendedMobilityInformation` (id 366, Ignore, Optional)
    pub extended_mobility_information: Option<ExtendedMobilityInformation>,
    /// `id-TargetCellCRNTI` (id 385, Ignore, Optional)
    pub target_cell_crnti: Option<CRnti>,
    /// `id-TimeSinceFailure` (id 386, Ignore, Optional)
    pub time_since_failure: Option<TimeSinceFailure>,
    /// IEs this version of the specification does not define here, as received (id, criticality, encoded value).
    pub unknown_ies: Vec<rt::ie::RawIe>,
}

impl HoReportExtIes {
    /// A value with the mandatory IEs given and every optional one absent.
    pub fn new() -> Self {
        Self {
            extended_mobility_information: None,
            target_cell_crnti: None,
            time_since_failure: None,
            unknown_ies: Vec::new(),
        }
    }
}

impl rt::AperEncode for HoReportExtIes {
    fn aper_encode(&self, w: &mut rt::BitWriter) -> rt::Result<()> {
        let mut ies: Vec<rt::ie::RawIe> = Vec::new();
        if let Some(x) = &self.extended_mobility_information {
            ies.push(rt::ie::RawIe::new(366, rt::ie::Criticality::Ignore, x)?);
        }
        if let Some(x) = &self.target_cell_crnti {
            ies.push(rt::ie::RawIe::new(385, rt::ie::Criticality::Ignore, x)?);
        }
        if let Some(x) = &self.time_since_failure {
            ies.push(rt::ie::RawIe::new(386, rt::ie::Criticality::Ignore, x)?);
        }
        ies.extend(self.unknown_ies.iter().cloned());
        rt::ie::write_container(w, rt::Size::range(1, 65535), &ies)
    }
}

impl rt::AperDecode for HoReportExtIes {
    fn aper_decode(r: &mut rt::BitReader<'_>) -> rt::Result<Self> {
        let mut s_extended_mobility_information: Option<ExtendedMobilityInformation> = None;
        let mut s_target_cell_crnti: Option<CRnti> = None;
        let mut s_time_since_failure: Option<TimeSinceFailure> = None;
        let mut unknown_ies = Vec::new();
        for ie in rt::ie::read_container(r, rt::Size::range(1, 65535))? {
            match ie.id {
                366 => rt::ie::set_once(&mut s_extended_mobility_information, 366, ie.decode()?)?,
                385 => rt::ie::set_once(&mut s_target_cell_crnti, 385, ie.decode()?)?,
                386 => rt::ie::set_once(&mut s_time_since_failure, 386, ie.decode()?)?,
                _ => unknown_ies.push(ie),
            }
        }
        Ok(Self {
            extended_mobility_information: s_extended_mobility_information,
            target_cell_crnti: s_target_cell_crnti,
            time_since_failure: s_time_since_failure,
            unknown_ies,
        })
    }
}

